    const own = room.players[room.seat], available = (own?.costPool ?? 0) + (own?.assets?.filter((c: any) => !c.tapped).length ?? 0), send = (play: any) => act({ type: continuous ? 'continuous-cast-choice' : 'effect-choice', choiceId: a.id, play }), skip = () => act({ type: continuous ? 'continuous-cast-choice' : 'effect-choice', choiceId: a.id, skip: true });
